def move_zeroes(nums):
    result = []
    for num in nums:                                        # collect every non-zero value, in order
        if num != 0:
            result.append(num)
    zero_count = len(nums) - len(result)
    result.extend([0] * zero_count)                          # fill the rest with zeros
    for i in range(len(nums)):
        nums[i] = result[i]                                     # copy back into the original array


if __name__ == "__main__":
    nums = [0, 1, 0, 3, 12]
    move_zeroes(nums)
    print(nums)

