import java.util.*;

public class Main {
    void moveZeroes(int[] nums) {
        List<Integer> result = new ArrayList<>();
        for (int num : nums) {                                    // collect every non-zero value, in order
            if (num != 0) result.add(num);
        }
        int zeroCount = nums.length - result.size();
        for (int i = 0; i < zeroCount; i++) result.add(0);         // fill the rest with zeros
        for (int i = 0; i < nums.length; i++) {
            nums[i] = result.get(i);                                 // copy back into the original array
        }
    }

    public static void main(String[] args) {
        int[] nums = {0, 1, 0, 3, 12};
        Main solution = new Main();
        solution.moveZeroes(nums);
        System.out.println(Arrays.toString(nums));
    }
}

