#include <bits/stdc++.h>
using namespace std;

void moveZeroes(vector<int>& nums) {
    vector<int> result;
    for (int num : nums) {                                     // collect every non-zero value, in order
        if (num != 0) result.push_back(num);
    }
    int zeroCount = (int)nums.size() - (int)result.size();
    for (int i = 0; i < zeroCount; i++) result.push_back(0);    // fill the rest with zeros
    for (int i = 0; i < (int)nums.size(); i++) {
        nums[i] = result[i];                                       // copy back into the original array
    }
}

int main() {
    vector<int> nums = {0, 1, 0, 3, 12};
    moveZeroes(nums);
    cout << "[";
    for (int i = 0; i < (int)nums.size(); i++) {
        cout << nums[i];
        if (i + 1 < (int)nums.size()) cout << ", ";
    }
    cout << "]" << endl;
    return 0;
}

